#' Campionamento con probabilità variabili (CPV)
#'
#' 
#' @param data .
#' @param weight_var Variabile quantitativa proporzionale al "peso" che ogni
#'   unità ha nella popolazione (es. fatturato, addetti, numero di abitanti).
#'   Deve essere finita e strettamente positiva per tutte le unità: valori
#'   mancanti, non finiti, negativi o nulli sono rifiutati. Le probabilità di
#'   SELEZIONE a ogni singola estrazione sono p_i = w_i / Σ w_i; da non
#'   confondere con le probabilità di inclusione nel campione.
#' @param id_var Variabile usata per identificare le singole unità nel
#'   dataset. Se specificata, la tabella "Unità estratte" mostra gli ID e i pesi
#'   dei soggetti selezionati.
#' @param tuto .
#' @param replacement Default TRUE: il CPV "classico" è con reinserimento
#'   perché le formule degli stimatori si semplificano. Se FALSE applica
#'   sample() senza reinserimento con probabilità proporzionali ai pesi (πps
#'   approssimato).
#' @param size_mode .
#' @param n .
#' @param f .
#' @param seed .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$extracted} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$out_freq} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
sampleppv <- function(
    data,
    weight_var,
    id_var,
    tuto = TRUE,
    replacement = TRUE,
    size_mode = "n",
    n = 30,
    f = 0.1,
    seed = 1) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("sampleppv requires jmvcore to be installed (restart may be required)")

    if ( ! missing(weight_var)) weight_var <- jmvcore::resolveQuo(jmvcore::enquo(weight_var))
    if ( ! missing(id_var)) id_var <- jmvcore::resolveQuo(jmvcore::enquo(id_var))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(weight_var), weight_var, NULL),
            `if`( ! missing(id_var), id_var, NULL))


    options <- sampleppvOptions$new(
        weight_var = weight_var,
        id_var = id_var,
        tuto = tuto,
        replacement = replacement,
        size_mode = size_mode,
        n = n,
        f = f,
        seed = seed)

    analysis <- sampleppvClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

